components.css:
.ds-hit {
  width: 2rem; height: 2rem; padding: 0; border: 0; border-radius: 0;
  background: transparent; color: #1a1a1a; display: inline-flex;
  align-items: center; justify-content: center; cursor: pointer;
}
.ds-hit:hover { background: rgba(26, 26, 26, 0.1); color: #1a1a1a; }
.ds-hit:focus-visible { outline: 1px solid #1a1a1a; outline-offset: 3px; }

.ds-hit-on {
  width: 2rem; height: 2rem; padding: 0; border: 0; border-radius: 0;
  background: #edb54a; color: #111111; display: inline-flex;
  align-items: center; justify-content: center; cursor: pointer; box-shadow: none;
}
.ds-hit-on:hover, .ds-hit-on:active { background: #edb54a; color: #111111; }
.ds-hit-on:focus-visible { outline: 1px solid #1a1a1a; outline-offset: 3px; }

.ds-panel {
  min-width: 17rem; min-height: 7.5rem; padding: 10px; border-radius: 0;
  border: 1px solid rgba(26, 26, 26, 0.14);
  background-color: rgb(214 214 214 / 97%);
  background-image:
    linear-gradient(rgba(26, 26, 26, 0.78), rgba(26, 26, 26, 0.78)),
    linear-gradient(rgba(26, 26, 26, 0.78), rgba(26, 26, 26, 0.78)),
    linear-gradient(rgba(26, 26, 26, 0.78), rgba(26, 26, 26, 0.78)),
    linear-gradient(rgba(26, 26, 26, 0.78), rgba(26, 26, 26, 0.78)),
    linear-gradient(rgba(26, 26, 26, 0.78), rgba(26, 26, 26, 0.78)),
    linear-gradient(rgba(26, 26, 26, 0.78), rgba(26, 26, 26, 0.78)),
    linear-gradient(rgba(26, 26, 26, 0.78), rgba(26, 26, 26, 0.78)),
    linear-gradient(rgba(26, 26, 26, 0.78), rgba(26, 26, 26, 0.78));
  background-size: 10px 1px, 1px 10px, 10px 1px, 1px 10px, 10px 1px, 1px 10px, 10px 1px, 1px 10px;
  background-position: 0 0, 0 0, 100% 0, 100% 0, 0 100%, 0 100%, 100% 100%, 100% 100%;
  background-repeat: no-repeat;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px); color: #1a1a1a;
}
.ds-panel-label {
  font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 12px; font-weight: 400;
  font-variant: small-caps; letter-spacing: 0.14em; color: #1a1a1a;
}

.ds-switch {
  position: relative; display: grid; grid-template-columns: 1fr 1fr;
  align-items: center; width: 4.75rem; height: 22px; border: 0; border-radius: 0;
  background: transparent; color: #3a3a3a; font-family: "IBM Plex Mono", ui-monospace, monospace;
  font-size: 10px; font-weight: 400; font-variant: small-caps;
  letter-spacing: 0.14em; padding: 0; cursor: pointer;
}
.ds-switch-glide {
  position: absolute; z-index: 0; top: 0; bottom: 0; left: 50%; width: 50%;
  background: #edb54a; pointer-events: none;
}
.ds-switch > span:not(.ds-switch-glide) { position: relative; z-index: 1; text-align: center; }
.ds-switch > span[data-hot="true"] { color: #111111; }
.ds-switch:focus-visible { outline: 1px solid #1a1a1a; outline-offset: 3px; }
.ds-switch:hover { color: #1a1a1a; }

.ds-tabs {
  position: relative; display: grid; grid-auto-flow: column; grid-auto-columns: 1fr;
  width: 16rem; height: 32px; gap: 0; padding: 0; background: transparent; border-radius: 0;
}
.ds-tab {
  position: relative; z-index: 1; height: 28px; border: 0; border-radius: 0;
  background: transparent; color: #3a3a3a; font-family: "IBM Plex Mono", ui-monospace, monospace;
  font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; cursor: pointer;
}
.ds-tab:hover { color: #1a1a1a; }
.ds-tab-on { color: #111111; background: #edb54a; }
.ds-tab-on:hover { color: #111111; background: #edb54a; }
.ds-tab:focus-visible { outline: 1px solid #1a1a1a; outline-offset: 3px; }

.ds-menu {
  display: flex; flex-direction: column; gap: 2px; min-width: 13rem;
  padding: 8px 6px; border-radius: 0; border: 1px solid rgba(26, 26, 26, 0.14);
  background: rgb(214 214 214 / 97%); box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(4px);
}
.ds-menu-item {
  border-radius: 0; background: transparent; color: #1a1a1a;
  font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 12px; padding: 6px 8px;
}
.ds-menu-item:hover, .ds-menu-item-on { background: #edb54a; color: #111111; box-shadow: none; }

.ds-section {
  display: grid; grid-template-columns: 32px minmax(0, 1fr); column-gap: 4px;
  align-items: center; width: 17rem; height: 32px; color: #1a1a1a;
}
.ds-section-mark {
  width: 8px; height: 8px; margin: auto; border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor; transform: rotate(-45deg);
}
.ds-section-label {
  font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 12px; font-weight: 400;
  font-variant: small-caps; letter-spacing: 0.14em; text-transform: none;
}

.ds-slider { position: relative; width: 12rem; height: 24px; display: flex; align-items: center; }
.ds-slider-track {
  position: relative; height: 1px; width: 100%; background: rgba(26, 26, 26, 0.28);
}
.ds-slider-track::after {
  content: ""; position: absolute; left: 0; right: 0; top: calc(100% + 4px); height: 6px;
  background-image:
    linear-gradient(rgba(26, 26, 26, 0.28), rgba(26, 26, 26, 0.28)),
    linear-gradient(rgba(26, 26, 26, 0.28), rgba(26, 26, 26, 0.28)),
    linear-gradient(rgba(26, 26, 26, 0.28), rgba(26, 26, 26, 0.28)),
    linear-gradient(rgba(26, 26, 26, 0.28), rgba(26, 26, 26, 0.28)),
    linear-gradient(rgba(26, 26, 26, 0.28), rgba(26, 26, 26, 0.28));
  background-size: 1px 6px, 1px 4px, 1px 4px, 1px 4px, 1px 6px;
  background-position: 0 0, 25% 2px, 50% 2px, 75% 2px, 100% 0;
  background-repeat: no-repeat;
}
.ds-slider-range { position: absolute; left: 0; width: 42%; height: 100%; background: #edb54a; }
.ds-slider-thumb { position: absolute; left: 42%; top: -6px; width: 1px; height: 13px; background: #edb54a; }
